import { useState, useRef, useEffect, Fragment } from 'react';
import { ChevronDown, ChevronRight, X } from 'lucide-react';
import { createPortal } from 'react-dom';

interface DropdownItem {
  label: string;
  onClick?: () => void;
  icon?: React.ReactNode;
  shortcut?: string;
  disabled?: boolean;
  danger?: boolean;
  children?: DropdownItem[];
  divider?: boolean;
}

interface DropdownProps {
  trigger: React.ReactNode;
  items: DropdownItem[];
  align?: 'left' | 'right';
  className?: string;
}

export default function Dropdown({ trigger, items, align = 'right', className = '' }: DropdownProps) {
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (triggerRef.current?.contains(e.target as Node) || menuRef.current?.contains(e.target as Node)) return;
      setOpen(false);
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!open) return;
      const enabledItems = items.filter((_, i) => !items[i].divider && !items[i].disabled);
      switch (e.key) {
        case 'Escape':
          setOpen(false);
          triggerRef.current?.focus();
          break;
        case 'ArrowDown':
          e.preventDefault();
          setActiveIndex(prev => (prev + 1) % enabledItems.length);
          break;
        case 'ArrowUp':
          e.preventDefault();
          setActiveIndex(prev => (prev - 1 + enabledItems.length) % enabledItems.length);
          break;
        case 'Enter':
        case ' ':
          e.preventDefault();
          if (activeIndex >= 0) {
            const item = enabledItems[activeIndex];
            item.onClick?.();
            if (!item.children) setOpen(false);
          }
          break;
      }
    };
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [open, items, activeIndex]);

  const renderItems = (itemsToRender: DropdownItem[]) => (
    <div className="py-1">
      {itemsToRender.map((item, index) => {
        if (item.divider) {
          return <div key={`divider-${index}`} className="h-px bg-white/10 my-1" role="separator" />;
        }
        const isSubmenu = item.children && item.children.length > 0;
        return (
          <div key={item.label} className="relative">
            {isSubmenu ? (
              <Submenu item={item} index={index} />
            ) : (
              <button
                onClick={() => {
                  item.onClick?.();
                  setOpen(false);
                }}
                disabled={item.disabled}
                className={`w-full flex items-center gap-2 px-3 py-2 text-sm transition-colors ${item.disabled ? 'opacity-50 cursor-not-allowed' : 'text-gray-300 hover:text-white hover:bg-white/5'} ${item.danger ? 'text-rose-400 hover:bg-rose-500/10' : ''}`}
                tabIndex={activeIndex === index && open ? 0 : -1}
                ref={el => { if (activeIndex === index && open) el?.focus(); }}
              >
                {item.icon && <span className="w-4 h-4 flex-shrink-0">{item.icon}</span>}
                <span className="flex-1 text-left">{item.label}</span>
                {item.shortcut && <span className="text-xs text-gray-500">{item.shortcut}</span>}
              </button>
            )}
          </div>
        );
      })}
    </div>
  );

  const Submenu = ({ item, index }: { item: DropdownItem; index: number }) => {
    const [subOpen, setSubOpen] = useState(false);
    return (
      <div className="relative">
        <button
          onClick={() => setSubOpen(!subOpen)}
          disabled={item.disabled}
          className={`w-full flex items-center gap-2 px-3 py-2 text-sm transition-colors ${item.disabled ? 'opacity-50 cursor-not-allowed' : 'text-gray-300 hover:text-white hover:bg-white/5'}`}
          aria-haspopup="true"
          aria-expanded={subOpen}
        >
          {item.icon && <span className="w-4 h-4 flex-shrink-0">{item.icon}</span>}
          <span className="flex-1 text-left">{item.label}</span>
          <ChevronRight className="w-4 h-4 text-gray-500" />
        </button>
        {subOpen && (
          <div className="absolute left-full top-0 ml-1 min-w-[180px] backdrop-blur-xl bg-white/5 border border-white/10 rounded-xl shadow-2xl py-1 z-50">
            {renderItems(item.children!)}
          </div>
        )}
      </div>
    );
  };

  const portalContent = (
    <div
      ref={menuRef}
      className={`fixed z-50 min-w-[200px] backdrop-blur-xl bg-white/5 border border-white/10 rounded-xl shadow-2xl ${align === 'right' ? 'right-0' : 'left-0'}`}
      role="menu"
      aria-orientation="vertical"
    >
      {renderItems(items)}
    </div>
  );

  return (
    <div className={`relative inline-block ${className}`}>
      <button
        ref={triggerRef}
        onClick={() => setOpen(!open)}
        className="flex items-center gap-1.5"
        aria-haspopup="true"
        aria-expanded={open}
      >
        {trigger}
        <ChevronDown className={`w-4 h-4 transition-transform ${open ? 'rotate-180' : ''}`} />
      </button>
      {open && createPortal(portalContent, document.body)}
    </div>
  );
}
